import{_ as t,o as a,c as i,a0 as n}from"./chunks/framework.IrjkP_YN.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"一个应届生的项目笔记","text":"AI 取名助手是怎么做出来的","tagline":"2027 届 · 西安 · 后端为主，前端是 AI 帮我搞的","actions":[{"theme":"brand","text":"开始读","link":"/posts/"},{"theme":"alt","text":"GitHub","link":"https://github.com/wangxihong-dev/ai-name-assistant"}]},"features":[{"title":"都是真事","details":"每篇都有具体的日期、具体的报错原文、具体的数字，你可以自己核。"},{"title":"弯路比结论多","details":"结论谁都能抄。我写的是当时怎么想错的、后来怎么发现的。"},{"title":"不懂的地方我会说不懂","details":"有些地方我到现在也没完全搞明白，那我就写「没搞明白」。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),s={name:"index.md"};function o(r,e,l,d,p,_){return a(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="这个项目是什么" tabindex="-1">这个项目是什么 <a class="header-anchor" href="#这个项目是什么" aria-label="Permalink to &quot;这个项目是什么&quot;">​</a></h2><p>一个取名网站，原来只做人名（诗经楚辞唐诗宋词 + 向量检索），2026 年 9 月开始加品牌／产品取名， 底下垫了一层商标法规则引擎：法条存在数据库里、禁用字样名录 158 条、模型只输出条款编号、 代码拿着编号回表取原文，这样模型没有机会改法条的字。</p><p>已经上线了，跑在一台 2 核 4G 的阿里云 ECS 上，六个 Docker 容器。</p><h2 id="为什么写这个" tabindex="-1">为什么写这个 <a class="header-anchor" href="#为什么写这个" aria-label="Permalink to &quot;为什么写这个&quot;">​</a></h2><p>秋招面试被问过「你这个 agent 是怎么设计的」，我发现自己讲不清楚——不是不会，是那些决定当时做完就忘了为什么。 写下来是逼自己把理由重新捋一遍。</p><p>顺便，如果我踩过的坑能让别人少踩一次，那也算有点用。</p><div class="go-app"><a href="/app/" target="_self">去用一下项目 →</a></div>',7)])])}const m=t(s,[["render",o]]);export{h as __pageData,m as default};
